package com.kailaxy.salaryledger.aibench;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public final class BenchmarkTest {
    interface Checked {void run()throws Exception;}
    private static void fails(String text,Checked c)throws Exception{try{c.run();fail("Expected rejection");}catch(Exception e){assertTrue(e.getMessage(),e.getMessage().contains(text));}}
    private static void u32(DataOutputStream o,long n)throws IOException{o.writeInt(Integer.reverseBytes((int)n));}
    private static void u64(DataOutputStream o,long n)throws IOException{o.writeLong(Long.reverseBytes(n));}
    private static void string(DataOutputStream o,String s)throws IOException{byte[] b=s.getBytes("UTF-8");u64(o,b.length);o.write(b);}
    private static byte[] model(String arch,int quant)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream o=new DataOutputStream(b);o.writeInt(0x47475546);u32(o,3);u64(o,1);u64(o,4);string(o,"general.architecture");u32(o,8);string(o,arch);for(String key:new String[]{"general.file_type","qwen2.embedding_length","qwen2.block_count"}){string(o,key);u32(o,4);u32(o,key.equals("general.file_type")?quant:key.contains("embedding")?896:24);}string(o,"weight");u32(o,1);u64(o,32);u32(o,2);u64(o,0);o.write(new byte[128]);return b.toByteArray();}
    private static ModelVerifier.Pin pin(byte[] bytes)throws Exception{StringBuilder s=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))s.append(String.format("%02x",b&255));return new ModelVerifier.Pin(s.toString(),"a".repeat(40),bytes.length);}
    @Test public void checksActualHashMetadataAndSize()throws Exception{byte[] bytes=model("qwen2",15);File dir=Files.createTempDirectory("bench-model").toFile(),file=new File(dir,"model.gguf");Files.write(file.toPath(),bytes);assertEquals("qwen2",ModelVerifier.verify(file,pin(bytes),()->false).get("general.architecture"));byte[] altered=bytes.clone();altered[altered.length-1]=1;Files.write(file.toPath(),altered);fails("SHA256",()->ModelVerifier.verify(file,pin(bytes),()->false));Files.write(file.toPath(),new byte[3]);fails("SIZE",()->ModelVerifier.verify(file,pin(bytes),()->false));}
    @Test public void importIsAtomicAndCancellationPreservesOldModel()throws Exception{byte[] bytes=model("qwen2",15);File dir=Files.createTempDirectory("bench-import").toFile(),file=new File(dir,"model.gguf");Files.write(file.toPath(),new byte[]{7});fails("CANCELLED",()->ModelVerifier.importModel(new ByteArrayInputStream(bytes),file,pin(bytes),()->true));assertArrayEquals(new byte[]{7},Files.readAllBytes(file.toPath()));assertFalse(new File(dir,"model.gguf.part").exists());ModelVerifier.importModel(new ByteArrayInputStream(bytes),file,pin(bytes),()->false);assertArrayEquals(bytes,Files.readAllBytes(file.toPath()));}
    @Test public void missingUnpinnedAndIncompatibleFilesFailClosed()throws Exception{File f=Files.createTempFile("bench-invalid",".gguf").toFile();fails("UNRESOLVED",()->ModelVerifier.verify(f,new ModelVerifier.Pin(null,null,0),()->false));byte[] wrong=model("llama",15);Files.write(f.toPath(),wrong);fails("INCOMPATIBLE",()->ModelVerifier.verify(f,pin(wrong),()->false));byte[] quant=model("qwen2",7);Files.write(f.toPath(),quant);fails("INCOMPATIBLE",()->ModelVerifier.verify(f,pin(quant),()->false));Files.write(f.toPath(),new byte[64]);fails("MAGIC",()->ModelVerifier.metadata(f,()->false));Files.delete(f.toPath());fails("NOT_INSTALLED",()->ModelVerifier.verify(f,pin(wrong),()->false));}
    @Test public void boundedRequestsAndConfigurations()throws Exception{for(int threads=2;threads<=4;threads++)new RunConfig(1024,threads,128,0,42);new RunConfig(2048,2,96,.6,42);for(int context:new int[]{0,512,4096})fails("configuration",()->new RunConfig(context,2,128,0,42));fails("configuration",()->new RunConfig(1024,8,128,0,42));fails("configuration",()->new RunConfig(1024,2,129,0,42));fails("configuration",()->new RunConfig(1024,2,128,Double.NaN,42));fails("synthetic",()->RunConfig.prompt("ok",""));fails("synthetic",()->RunConfig.prompt("ok","x".repeat(4001)));}
    @Test public void serialWorkerCancelsWithoutBlockingAndClosesAfterTask()throws Exception{CountDownLatch running=new CountDownLatch(1),release=new CountDownLatch(1),done=new CountDownLatch(1);AtomicBoolean destroyed=new AtomicBoolean();AtomicInteger cancellation=new AtomicInteger();String main=Thread.currentThread().getName();SerialSession s=new SerialSession(()->{},()->{cancellation.incrementAndGet();release.countDown();},()->{},()->destroyed.set(true));assertTrue(s.submit(()->{assertNotEquals(main,Thread.currentThread().getName());running.countDown();try{release.await();}catch(InterruptedException e){throw new RuntimeException(e);}assertFalse(destroyed.get());},e->done.countDown()));assertTrue(running.await(2,TimeUnit.SECONDS));assertFalse(s.submit(()->fail("Overlapping work"),e->{}));long start=System.nanoTime();s.cancel();assertTrue(System.nanoTime()-start<100_000_000);s.close();assertTrue(done.await(2,TimeUnit.SECONDS));assertTrue(s.await(2000));assertTrue(destroyed.get());assertTrue(cancellation.get()>0);assertFalse(s.submit(()->{},e->{}));}
    @Test public void failureAllowsRecoveryAndSuspendUnloadsOnWorker()throws Exception{CountDownLatch failed=new CountDownLatch(1),unloaded=new CountDownLatch(1);SerialSession s=new SerialSession(()->{},()->{},unloaded::countDown,()->{});assertTrue(s.submit(()->{throw new IllegalStateException("test");},e->{assertNotNull(e);failed.countDown();}));assertTrue(failed.await(2,TimeUnit.SECONDS));assertTrue(s.submit(()->{},e->{}));s.suspend();assertTrue(unloaded.await(2,TimeUnit.SECONDS));s.close();assertTrue(s.await(2000));}
}
